<script setup lang="ts">
import { computed } from 'vue'
import { useVoiceStore } from '@stores/useVoiceStore'
import SettingSlider from './SettingSlider.vue'
import SettingSelect from './SettingSelect.vue'

const voiceStore = useVoiceStore()
const settings = computed(() => voiceStore.settings)
const outputDevices = computed(() => voiceStore.availableOutputDevices)

const deviceOptions = computed(() => [
  { value: '', label: 'Standardgerät verwenden' },
  ...outputDevices.value.map(device => ({
    value: device.deviceId,
    label: device.label || `Lautsprecher ${device.deviceId.slice(0, 8)}`,
  })),
])
</script>

<template>
  <div class="settings-panel">
    <SettingSelect
      label="Ausgabegerät"
      :model-value="settings.outputDeviceId"
      :options="deviceOptions"
      @update:model-value="voiceStore.updateSettings({ outputDeviceId: $event })"
    />

    <SettingSlider
      label="Lautstärke"
      :model-value="settings.outputVolume"
      @update:model-value="voiceStore.updateSettings({ outputVolume: $event })"
    />
  </div>
</template>
