<script setup lang="ts">
import { computed } from 'vue'
import { useVoiceStore } from '@stores/useVoiceStore'
import SettingSlider from './SettingSlider.vue'
import SettingToggle from './SettingToggle.vue'

const voiceStore = useVoiceStore()
const settings = computed(() => voiceStore.settings)
</script>

<template>
  <div class="settings-panel">
    <SettingToggle
      label="Overlay aktivieren"
      description="Zeigt Statusinformationen über dem Spiel im Browser-Tab"
      :model-value="settings.overlayEnabled"
      @update:model-value="voiceStore.updateSettings({ overlayEnabled: $event })"
    />

    <SettingToggle
      label="Mikrofon-Status anzeigen"
      :model-value="settings.overlayShowMicrophone"
      :visible="settings.overlayEnabled"
      @update:model-value="voiceStore.updateSettings({ overlayShowMicrophone: $event })"
    />

    <SettingSlider
      label="Deckkraft"
      :model-value="settings.overlayOpacity"
      :visible="settings.overlayEnabled"
      @update:model-value="voiceStore.updateSettings({ overlayOpacity: $event })"
    />

    <SettingToggle
      label="Immer anzeigen"
      description="Auch anzeigen, wenn der Tab nicht im Vordergrund ist"
      :model-value="settings.overlayAlwaysVisible"
      :visible="settings.overlayEnabled"
      @update:model-value="voiceStore.updateSettings({ overlayAlwaysVisible: $event })"
    />
  </div>
</template>
