<script setup lang="ts">
/** One labelled control, used by every settings panel to keep spacing equal. */
withDefaults(defineProps<{
  label: string
  description?: string
  /** Hides the row entirely when the feature it belongs to is off. */
  visible?: boolean
}>(), { description: undefined, visible: true })
</script>

<template>
  <div v-show="visible" class="setting-row">
    <label class="setting-row-label">
      <span>{{ label }}</span>
      <small v-if="description" class="setting-row-description">{{ description }}</small>
    </label>
    <div class="setting-row-control">
      <slot />
    </div>
  </div>
</template>
