<script setup lang="ts">
import { computed, ref, onUnmounted } from 'vue'
import { useVoiceStore } from '@stores/useVoiceStore'
import SettingRow from './SettingRow.vue'
import SettingSlider from './SettingSlider.vue'
import SettingToggle from './SettingToggle.vue'
import SettingSelect from './SettingSelect.vue'

const voiceStore = useVoiceStore()
const settings = computed(() => voiceStore.settings)
const inputDevices = computed(() => voiceStore.availableInputDevices)

const deviceOptions = computed(() => [
  { value: '', label: 'Standardgerät verwenden' },
  ...inputDevices.value.map(device => ({
    value: device.deviceId,
    label: device.label || `Mikrofon ${device.deviceId.slice(0, 8)}`,
  })),
])

// The mod shows the raw dB value here, not a percentage.
const dbFormat = (value: number) => `${Math.round(value)} dB`

const testTonePlaying = ref(false)
let testAudioContext: AudioContext | null = null
let testOscillator: OscillatorNode | null = null

function playTestTone() {
  if (testTonePlaying.value) {
    stopTestTone()
    return
  }
  try {
    testAudioContext = new AudioContext()
    testOscillator = testAudioContext.createOscillator()
    const gain = testAudioContext.createGain()
    testOscillator.type = 'sine'
    testOscillator.frequency.value = 440
    gain.gain.value = 0.1
    testOscillator.connect(gain)
    gain.connect(testAudioContext.destination)
    testOscillator.start()
    testTonePlaying.value = true
  } catch (error) {
    console.error('Test tone error:', error)
  }
}

function stopTestTone() {
  testOscillator?.stop()
  testOscillator?.disconnect()
  testOscillator = null
  void testAudioContext?.close()
  testAudioContext = null
  testTonePlaying.value = false
}

onUnmounted(stopTestTone)
</script>

<template>
  <div class="settings-panel">
    <SettingSelect
      label="Eingabegerät"
      :model-value="settings.inputDeviceId"
      :options="deviceOptions"
      @update:model-value="voiceStore.updateSettings({ inputDeviceId: $event })"
    />

    <SettingSlider
      label="Mikrofon-Lautstärke"
      :model-value="settings.inputVolume"
      @update:model-value="voiceStore.updateSettings({ inputVolume: $event })"
    />

    <SettingToggle
      label="Push-to-Talk"
      description="Nur senden, solange die Taste gedrückt ist"
      :model-value="settings.pushToTalk"
      @update:model-value="voiceStore.updateSettings({ pushToTalk: $event })"
    />

    <SettingRow label="Push-to-Talk Taste" :visible="settings.pushToTalk">
      <input
        class="setting-select"
        type="text"
        readonly
        :value="settings.pushToTalkKey.replace('Key', '')"
        @keydown.prevent="voiceStore.updateSettings({ pushToTalkKey: $event.code })"
      >
    </SettingRow>

    <SettingSlider
      label="Sprachaktivierung"
      description="Leiser als dieser Wert gilt als Stille"
      :model-value="settings.voiceActivationThreshold"
      :min="-100"
      :max="0"
      :step="1"
      :format="dbFormat"
      @update:model-value="voiceStore.updateSettings({ voiceActivationThreshold: $event })"
    />

    <SettingSlider
      label="Stimmfilter"
      description="Audio unterhalb dieser Grenze wird verworfen"
      :model-value="settings.voiceFilterLevel"
      :min="-100"
      :max="0"
      :step="1"
      :format="dbFormat"
      @update:model-value="voiceStore.updateSettings({ voiceFilterLevel: $event })"
    />

    <SettingToggle
      label="Rauschunterdrückung (RNNoise)"
      description="Entfernt Hintergrundgeräusche mit KI"
      :model-value="settings.noiseSuppression"
      @update:model-value="voiceStore.updateSettings({ noiseSuppression: $event })"
    />

    <SettingSlider
      label="Stärke"
      description="Höhere Werte entfernen mehr Rauschen"
      :model-value="settings.noiseSuppressionLevel"
      :step="0.05"
      :visible="settings.noiseSuppression"
      @update:model-value="voiceStore.updateSettings({ noiseSuppressionLevel: $event })"
    />

    <SettingToggle
      label="Echo-Unterdrückung"
      :model-value="settings.echoCancellation"
      @update:model-value="voiceStore.updateSettings({ echoCancellation: $event })"
    />

    <SettingToggle
      label="Automatische Verstärkungsregelung"
      :model-value="settings.autoGainControl"
      @update:model-value="voiceStore.updateSettings({ autoGainControl: $event })"
    />

    <SettingToggle
      label="Signalton bei Sprechbeginn"
      :model-value="settings.voiceActivityTone"
      @update:model-value="voiceStore.updateSettings({ voiceActivityTone: $event })"
    />

    <SettingRow label="Testton abspielen">
      <button
        class="btn btn-sm"
        :class="testTonePlaying ? 'btn-primary' : 'btn-secondary'"
        @click="playTestTone"
      >
        {{ testTonePlaying ? 'Stoppen' : 'Abspielen' }}
      </button>
    </SettingRow>
  </div>
</template>
