<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useAuthStore } from '@stores/useAuthStore'
import { useVoiceStore } from '@stores/useVoiceStore'
import { useHead } from '@vueuse/head'
import MicSettings from '@components/settings/MicSettings.vue'
import SpeakerSettings from '@components/settings/SpeakerSettings.vue'
import SpatialAudioSettings from '@components/settings/SpatialAudioSettings.vue'
import ChatSettings from '@components/settings/ChatSettings.vue'
import OverlaySettings from '@components/settings/OverlaySettings.vue'

const authStore = useAuthStore()
const voiceStore = useVoiceStore()

useHead({ title: 'Einstellungen - SimpleVoiceChat' })

/** The mod splits its options into panels, so the page does the same. */
const panels = [
  { id: 'microphone', label: 'Mikrofon', icon: 'mic', component: MicSettings },
  { id: 'speaker', label: 'Lautsprecher', icon: 'speaker', component: SpeakerSettings },
  { id: 'spatial', label: '3D-Audio', icon: 'spatial', component: SpatialAudioSettings },
  { id: 'chat', label: 'Chat', icon: 'chat', component: ChatSettings },
  { id: 'overlay', label: 'Overlay', icon: 'overlay', component: OverlaySettings },
  { id: 'account', label: 'Account', icon: 'account', component: null },
] as const

type PanelId = typeof panels[number]['id']

const activePanel = ref<PanelId>('microphone')
const settings = computed(() => voiceStore.settings)
const activeComponent = computed(() => panels.find(p => p.id === activePanel.value)?.component ?? null)

async function refreshDevices() {
  await voiceStore.requestDevicePermissions()
  voiceStore.updateInputDevices()
  voiceStore.updateOutputDevices()
}

function handleLogout() {
  authStore.clearAuth()
}

onMounted(refreshDevices)
</script>

<template>
  <div class="settings-view">
    <header class="settings-header">
      <button @click="$router.push('/voice')" class="btn btn-icon" aria-label="Zurück zum Sprachchat">
        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <path d="M19 12H5M12 19l-7-7 7-7" />
        </svg>
      </button>
      <h1>Einstellungen</h1>
    </header>

    <div class="settings-body">
      <nav class="settings-nav" aria-label="Einstellungsbereiche">
        <button
          v-for="panel in panels"
          :key="panel.id"
          class="settings-nav-item"
          :class="{ 'is-active': activePanel === panel.id }"
          :aria-current="activePanel === panel.id ? 'page' : undefined"
          @click="activePanel = panel.id"
        >
          {{ panel.label }}
        </button>
      </nav>

      <main class="settings-main">
        <h2 class="settings-panel-title">
          {{ panels.find(p => p.id === activePanel)?.label }}
        </h2>

        <component :is="activeComponent" v-if="activeComponent" />

        <section v-else-if="activePanel === 'account'" class="settings-panel">
          <div class="setting-group">
            <p><strong>Benutzername:</strong> {{ authStore.username }}</p>
            <p><strong>User ID:</strong> {{ authStore.userId }}</p>
          </div>
          <div class="setting-group">
            <button @click="handleLogout" class="btn btn-danger">Abmelden</button>
          </div>
        </section>
      </main>
    </div>
  </div>
</template>

<style scoped src="./settings-view.css"></style>
