<script setup lang="ts">
import SettingRow from './SettingRow.vue'
/** Colour picker row used for the chat text and background colours. */
withDefaults(defineProps<{
  modelValue: string
  label: string
  description?: string
}>(), { description: undefined })

const emit = defineEmits<{ 'update:modelValue': [value: string] }>()

function onInput(event: Event) {
  const target = event.target as HTMLInputElement | null
  emit('update:modelValue', target?.value ?? '#ffffff')
}
</script>

<template>
  <SettingRow :label="label" :description="description">
    <div class="setting-slider-row">
      <input type="color" class="setting-color" :value="modelValue" @input="onInput">
      <span class="setting-value">{{ modelValue.toUpperCase() }}</span>
    </div>
  </SettingRow>
</template>
