<script setup lang="ts">
import { computed } from 'vue'
import { useVoiceStore } from '@stores/useVoiceStore'
import SettingSlider from './SettingSlider.vue'
import SettingToggle from './SettingToggle.vue'
import SettingSelect from './SettingSelect.vue'
import type { AudioEngineId } from '../../types'

const voiceStore = useVoiceStore()
const settings = computed(() => voiceStore.settings)

const engineOptions = [
  { value: 'automatic', label: 'Automatisch' },
  { value: 'legacy', label: 'Legacy' },
  { value: 'openal', label: 'OpenAL' },
]

// The mod shows the hearing range in blocks, not as a percentage.
const blockFormat = (value: number) => `${Math.round(value)} Blöcke`
</script>

<template>
  <div class="settings-panel">
    <SettingToggle
      label="Räumliches Audio"
      description="Positioniert Sprachchat räumlich im Raum"
      :model-value="settings.spatialAudio"
      @update:model-value="voiceStore.updateSettings({ spatialAudio: $event })"
    />

    <SettingSlider
      label="Hörreichweite"
      description="Spieler außerhalb dieser Distanz werden leiser"
      :model-value="settings.audibleRange"
      :min="8"
      :max="128"
      :step="1"
      :format="blockFormat"
      :visible="settings.spatialAudio"
      @update:model-value="voiceStore.updateSettings({ audibleRange: $event })"
    />

    <SettingSlider
      label="Entfernungs-Immersion"
      description="Wie stark die Entfernung den Klang beeinflusst"
      :model-value="settings.distanceImmersion"
      :visible="settings.spatialAudio"
      @update:model-value="voiceStore.updateSettings({ distanceImmersion: $event })"
    />

    <SettingToggle
      label="Eigene Stimme verstärken"
      description="Hält deine eigene Stimme unabhängig von der Entfernung hörbar"
      :model-value="settings.amplifyOwnVoice"
      :visible="settings.spatialAudio"
      @update:model-value="voiceStore.updateSettings({ amplifyOwnVoice: $event })"
    />

    <SettingSelect
      label="Audio-Engine"
      description="Der Browser wählt automatisch die beste Engine"
      :model-value="settings.audioEngine"
      :options="engineOptions"
      @update:model-value="voiceStore.updateSettings({ audioEngine: $event as AudioEngineId })"
    />

    <SettingToggle
      label="Natürliches Hören (HRTF)"
      description="Nutzt die räumliche Berechnung des Browsers statt manueller Berechnung"
      :model-value="settings.useHrtf"
      :visible="settings.spatialAudio"
      @update:model-value="voiceStore.updateSettings({ useHrtf: $event })"
    />

    <SettingToggle
      label="An Kamera drehen"
      description="Richtet den Hörraum an der Blickrichtung aus"
      :model-value="settings.rotateWithCamera"
      :visible="settings.spatialAudio"
      @update:model-value="voiceStore.updateSettings({ rotateWithCamera: $event })"
    />
  </div>
</template>
