<script setup lang="ts">
import { computed } from 'vue'
import { useVoiceStore } from '@stores/useVoiceStore'
import SettingSlider from './SettingSlider.vue'
import SettingToggle from './SettingToggle.vue'
import SettingSelect from './SettingSelect.vue'
import SettingRowColor from './SettingRowColor.vue'
import type { ChatPosition, ChatVisibility } from '../../types'

const voiceStore = useVoiceStore()
const settings = computed(() => voiceStore.settings)

const visibilityOptions = [
  { value: 'always', label: 'Immer anzeigen' },
  { value: 'never', label: 'Nie anzeigen' },
  { value: 'mentions', label: 'Nur bei Erwähnung' },
]

const positionOptions = [
  { value: 'bottom', label: 'Unten' },
  { value: 'top', label: 'Oben' },
  { value: 'right', label: 'Rechts' },
  { value: 'left', label: 'Links' },
]

const pixelFormat = (value: number) => `${Math.round(value)} px`
const opacityFormat = (value: number) => `${Math.round(value * 100)}%`
</script>

<template>
  <div class="settings-panel">
    <SettingSelect
      label="Chat-Sichtbarkeit"
      :model-value="settings.chatVisibility"
      :options="visibilityOptions"
      @update:model-value="voiceStore.updateSettings({ chatVisibility: $event as ChatVisibility })"
    />

    <SettingSelect
      label="Chat-Position"
      :model-value="settings.chatPosition"
      :options="positionOptions"
      :visible="settings.chatVisibility !== 'never'"
      @update:model-value="voiceStore.updateSettings({ chatPosition: $event as ChatPosition })"
    />

    <SettingSlider
      label="Chat-Höhe"
      :model-value="settings.chatBoxHeight"
      :min="80"
      :max="600"
      :step="10"
      :format="pixelFormat"
      :visible="settings.chatVisibility !== 'never'"
      @update:model-value="voiceStore.updateSettings({ chatBoxHeight: $event })"
    />

    <SettingSlider
      label="Chat-Breite"
      :model-value="settings.chatBoxWidth"
      :min="180"
      :max="900"
      :step="10"
      :format="pixelFormat"
      :visible="settings.chatVisibility !== 'never'"
      @update:model-value="voiceStore.updateSettings({ chatBoxWidth: $event })"
    />

    <SettingSlider
      label="Hintergrund-Deckkraft"
      :model-value="settings.chatBackgroundOpacity"
      :format="opacityFormat"
      :visible="settings.chatVisibility !== 'never'"
      @update:model-value="voiceStore.updateSettings({ chatBackgroundOpacity: $event })"
    />

    <SettingRowColor
      label="Textfarbe"
      :model-value="settings.chatTextColor"
      @update:model-value="voiceStore.updateSettings({ chatTextColor: $event })"
    />

    <SettingRowColor
      label="Hintergrundfarbe"
      :model-value="settings.chatBackgroundColor"
      @update:model-value="voiceStore.updateSettings({ chatBackgroundColor: $event })"
    />

    <SettingToggle
      label="Umrandeter Text"
      :model-value="settings.chatOutline"
      :visible="settings.chatVisibility !== 'never'"
      @update:model-value="voiceStore.updateSettings({ chatOutline: $event })"
    />

    <SettingToggle
      label="Chat ausblenden, wenn leer"
      :model-value="settings.hideChatWhenNoMessages"
      @update:model-value="voiceStore.updateSettings({ hideChatWhenNoMessages: $event })"
    />

    <SettingToggle
      label="Chat-Rauschen blockieren"
      description="Unterdrückt störende System- und Spielgeräusche im Chat"
      :model-value="settings.blockChatNoise"
      @update:model-value="voiceStore.updateSettings({ blockChatNoise: $event })"
    />
  </div>
</template>
