<script setup lang="ts">
import SettingRow from './SettingRow.vue'
/** Labelled range input that shows its current value. */
const props = withDefaults(defineProps<{
  modelValue: number
  label: string
  min?: number
  max?: number
  step?: number
  /** Formats the readout, e.g. percent or dB. */
  format?: (value: number) => string
}>(), { min: 0, max: 1, step: 0.01, format: undefined })

const emit = defineEmits<{ 'update:modelValue': [value: number] }>()

function display(value: number): string {
  return props.format ? props.format(value) : `${Math.round(value * 100)}%`
}

function onInput(event: Event) {
  const target = event.target as HTMLInputElement | null
  emit('update:modelValue', target?.valueAsNumber ?? 0)
}
</script>

<template>
  <SettingRow :label="label">
    <div class="setting-slider-row">
      <input
        type="range"
        class="setting-slider"
        :min="min"
        :max="max"
        :step="step"
        :value="modelValue"
        @input="onInput"
      />
      <span class="setting-value">{{ display(modelValue) }}</span>
    </div>
  </SettingRow>
</template>
